package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import org.springframework.stereotype.Component;
/** A typed association contract. OCR is evidence text, never claimed visual understanding. */
@Component public final class MultimodalQaSchema {
 public static final String PREFIX="multimodal-qa-v1\n",KIND="MULTIMODAL_QA";
 private final JsonMapper json=JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,DeserializationFeature.FAIL_ON_TRAILING_TOKENS,DeserializationFeature.FAIL_ON_MISSING_CREATOR_PROPERTIES).propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).build();
 public record Input(String key,PermissionProtocol.Basis source,String rightsRevision,DatasetProtocol.EvidenceRef evidence,String literal,String representation){}
 public record Question(String key,String sectionId,String question,List<String> inputKeys){public Question{inputKeys=List.copyOf(inputKeys);}}
 public record Selection(String schemaVersion,String scenarioKind,String capability,String failurePolicy,PermissionProtocol.Basis reviewRule,List<Input> inputs,List<Question> questions){public Selection{inputs=List.copyOf(inputs);questions=List.copyOf(questions);}}
 public Selection read(JsonNode n)throws Exception{try{var s=json.treeToValue(n,Selection.class);if(!"1.0.0".equals(s.schemaVersion())||!KIND.equals(s.scenarioKind())||!"PARSED_EVIDENCE_QA".equals(s.capability())||!"ABSTAIN_ON_MISSING_OR_CONFLICTING_EVIDENCE".equals(s.failurePolicy())||s.inputs().isEmpty()||s.inputs().size()>64||s.questions().isEmpty()||s.questions().size()>64)bad();basis(s.reviewRule());var keys=new HashSet<String>();var refs=new HashSet<DatasetProtocol.EvidenceRef>();
  for(var i:s.inputs()){key(i.key());if(!keys.add(i.key())||!refs.add(i.evidence()))bad();basis(i.source());WireValues.uuid(i.rightsRevision());ProjectSchema.text(i.literal(),8000);new TaskSourceReadReceiptSchema(new PermissionSchema()).evidence(tree(i.evidence()));if(!i.source().version_id().equals(i.evidence().sourceVersion())||!WireValues.sha256(i.literal().getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(i.evidence().quoteHash()))bad();String expected="IMAGE".equals(i.evidence().locator().kind())?"IMAGE_OCR_TEXT":"PARSED_TEXT";if(!expected.equals(i.representation()))bad();}
  var questions=new HashSet<String>();var used=new HashSet<String>();for(var q:s.questions()){key(q.key());if(!questions.add(q.key())||q.inputKeys().isEmpty()||new HashSet<>(q.inputKeys()).size()!=q.inputKeys().size()||!keys.containsAll(q.inputKeys()))bad();used.addAll(q.inputKeys());WireValues.uuid(q.sectionId());ProjectSchema.text(q.question(),2000);}if(!used.equals(keys))bad();return s;}catch(IllegalArgumentException|NullPointerException e){throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}}
 public JsonNode tree(Object o){return json.valueToTree(o);}public Selection definition(String d)throws Exception{if(!d.startsWith(PREFIX))bad();return read(json.readTree(d.substring(PREFIX.length())));}public String definition(JsonNode n)throws Exception{String d=PREFIX+new String(ContentReadAuthorization.canonicalBytes(tree(read(n))),java.nio.charset.StandardCharsets.UTF_8);if(d.length()>131072)bad();return d;}
 public void author(JsonNode a)throws Exception{String d=a.required("specification").required("INPUTS").required("definition").asText();if(!d.startsWith(PREFIX))return;var s=definition(d);var knowledge=new HashSet<PermissionProtocol.Basis>();for(var r:a.required("specification").required("APPLICABLE_KNOWLEDGE").required("evidence"))knowledge.add(basis(r));for(var i:s.inputs())if(!knowledge.contains(i.source())||!a.required("project_id").asText().equals(i.evidence().projectId()))bad();var rules=new HashSet<PermissionProtocol.Basis>();for(var r:a.required("specification").required("TASK_RULES").required("evidence"))rules.add(basis(r));if(!rules.contains(s.reviewRule()))bad();}
 private PermissionProtocol.Basis basis(JsonNode n){return new PermissionProtocol.Basis(n.required("version_id").asText(),n.required("content_sha256").asText());}private static void basis(PermissionProtocol.Basis b){WireValues.uuid(b.version_id());WireValues.hash(b.content_sha256());}private static void key(String k){if(k==null||!k.matches("[A-Za-z][A-Za-z0-9_-]{0,63}"))bad();}private static void bad(){throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}
}
